drop policy if exists cycles_write on public.training_cycles;
create policy cycles_read on public.training_cycles for select to authenticated using (public.is_assigned_coach(client_id) or (client_id = (select public.iberfit_client_id()) and status = 'publicado'::public.publication_status));
create policy cycles_insert_coach on public.training_cycles for insert to authenticated with check (public.is_assigned_coach(client_id));
create policy cycles_update_coach on public.training_cycles for update to authenticated using (public.is_assigned_coach(client_id)) with check (public.is_assigned_coach(client_id));
create policy cycles_delete_coach on public.training_cycles for delete to authenticated using (public.is_assigned_coach(client_id));
drop policy if exists sessions_read on public.sessions;
drop policy if exists sessions_write on public.sessions;
create policy sessions_read on public.sessions for select to authenticated using (public.is_assigned_coach(client_id) or (client_id = (select public.iberfit_client_id()) and status = 'publicado'::public.publication_status));
create policy sessions_insert_coach on public.sessions for insert to authenticated with check (public.is_assigned_coach(client_id));
create policy sessions_update_coach on public.sessions for update to authenticated using (public.is_assigned_coach(client_id)) with check (public.is_assigned_coach(client_id));
